- t2: mutex_lock {"resource": "main::a"}; mutex_lock {"resource": "main::b"}; mutex_unlock {"resource": "main::b"}; mutex_unlock {"resource": "main::a"}; return {}
- t3: mutex_lock {"resource": "main::c"}; mutex_lock {"resource": "main::d"}; mutex_unlock {"resource": "main::d"}; mutex_unlock {"resource": "main::c"}; return {}
- t4: mutex_lock {"resource": "main::c"}; mutex_lock {"resource": "main::d"}; mutex_unlock {"resource": "main::d"}; mutex_unlock {"resource": "main::c"}; return {}

